<?php
$env=[];foreach(file('C:/laragon/www/yayasan-app/.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)as$l){if(str_starts_with(trim($l),'#')||!str_contains($l,'='))continue;[$k,$v]=explode('=',$l,2);$env[trim($k)]=trim($v," \"'");}$host='127.0.0.1';$port='5432';$user='yayasan_app';$pass=$env['DB_PASSWORD']??'';$target='yayasan_midtrans_schema_test';$pdo=new PDO("pgsql:host=$host;port=$port;dbname=postgres",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$identity=$pdo->query('SELECT current_database(),current_user,inet_server_addr(),inet_server_port()')->fetch(PDO::FETCH_NUM);$db=$pdo->prepare('SELECT datname,datallowconn,has_database_privilege(current_user,datname,\'CONNECT\') FROM pg_database WHERE datname=?');$db->execute([$target]);$row=$db->fetch(PDO::FETCH_NUM);$result=['maintenance_connection'=>['database'=>$identity[0],'user'=>$identity[1],'host'=>$identity[2],'port'=>$identity[3]],'target_database_catalog'=>$row?:null,'target_exists'=>(bool)$row,'target_connect_privilege'=>$row?(bool)$row[2]:false];if($row&&$row[2]){try{$t=new PDO("pgsql:host=$host;port=$port;dbname=$target",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$result['target_identity']=$t->query('SELECT current_database(),current_user,inet_server_addr(),inet_server_port()')->fetch(PDO::FETCH_NUM);$result['schema_privileges']=$t->query("SELECT has_schema_privilege(current_user,'public','USAGE'),has_schema_privilege(current_user,'public','CREATE')")->fetch(PDO::FETCH_NUM);$result['tables']=$t->query("SELECT tablename FROM pg_tables WHERE schemaname='public' ORDER BY tablename")->fetchAll(PDO::FETCH_COLUMN);$result['empty']=count($result['tables'])===0;}catch(Throwable$e){$result['target_runtime_error']=$e->getMessage();}}echo json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),PHP_EOL;
